#!/usr/bin/env node
import { spawnSync } from "node:child_process";
import { fileURLToPath } from "node:url";
import path from "node:path";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "../../..");
const bin = path.join(root, "bin/greet.js");

const cases = [
  { feature: "greets a given name", args: ["ada"], expect: "hello, ada\n" },
  { feature: "defaults to world", args: [], expect: "hello, world\n" },
  { feature: "prints usage on --help", args: ["--help"], expect: "usage: greet [name]\n" },
];

let failures = 0;
for (const { feature, args, expect } of cases) {
  const result = spawnSync(process.execPath, [bin, ...args], { encoding: "utf8" });
  const passed = result.status === 0 && result.stdout === expect && result.stderr === "";
  console.log(
    `${passed ? "PASS" : "FAIL"} ${feature}: args=${JSON.stringify(args)} ` +
      `exit=${result.status} stdout=${JSON.stringify(result.stdout)}`,
  );
  if (!passed) {
    failures += 1;
    console.error(`  expected exit 0 stdout=${JSON.stringify(expect)} stderr=""`);
    if (result.stderr) console.error(`  stderr=${JSON.stringify(result.stderr)}`);
  }
}

if (failures > 0) {
  console.error(`verify-greet: ${failures}/${cases.length} case(s) failed`);
  process.exit(1);
}
console.log(`verify-greet: ${cases.length}/${cases.length} cases passed`);

